def _slug(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", value.casefold()).strip("_")


def _audience_groups_for(model: str) -> list[str]:
    lowered = model.casefold()
    groups: list[str] = []
    if any(token in lowered for token in ("b2b", "enterprise", "ulgurji", "distribyutsiya", "korporativ", "retainer", "saas", "license", "oem", "wholesale")):
        groups.append("business")
    if any(token in lowered for token in ("b2c", "d2c", "retail", "freemium", "obuna", "course", "service", "consumer", "membership", "ticket")):
        groups.append("consumer")
    if any(token in lowered for token in ("b2g", "davlat", "grant", "ppp", "tarif", "public", "municipal", "government")):
        groups.append("public")
    if any(token in lowered for token in ("license", "litsenziya", "hamkorlik", "sug'urta", "creator", "consult", "agency", "professional", "coach")):
        groups.append("professional")
    return groups or ["business", "consumer"]


def build_brand_taxonomy(base: dict[str, Any]) -> dict[str, Any]:
    """Build searchable brand taxonomy.

    Nested tree is intentionally shallow for payload size:
    category -> children (internal directions) + category.activities (recommended).
    Full 100+ catalogs live under ``catalog`` for SmartSelect fallback search.
    """
    categories: list[dict[str, Any]] = []
    total_internal_directions = 0
    for key, label, branches, mode, keywords, risk_keywords in CATEGORY_SEEDS:
        activity_values = sorted(set(ACTIVITIES_BY_MODE.get(mode, ACTIVITIES_BY_MODE["mixed"])), key=str.casefold)
        model_values = sorted(set(MODELS_BY_MODE.get(mode, MODELS_BY_MODE["mixed"])), key=str.casefold)
        activity_rows = [
            {
                "key": _slug(activity),
                "value": activity,
                "label": activity,
                "business_models": [
                    {
                        "key": _slug(model),
                        "value": model,
                        "label": model,
                        "audience_groups": _audience_groups_for(model),
                    }
                    for model in model_values
                ],
            }
            for activity in activity_values
        ]
        children = [
            {
                "key": _slug(branch),
                "value": branch,
                "label": branch,
                # Pointer only — full activity list lives on the parent category
                # (keeps JSON small while preserving hierarchy UX).
                "activities": activity_rows,
            }
            for branch in sorted(_items(branches), key=str.casefold)
        ]
        # Avoid duplicating the entire activity tree under every child.
        # Children keep a shared-looking structure for older clients, but we
        # only embed activities once on the category for new clients.
        lean_children = [
            {
                "key": child["key"],
                "value": child["value"],
                "label": child["label"],
            }
            for child in children
        ]
        total_internal_directions += len(lean_children)
        categories.append(
            {
                "key": key,
                "value": label,
                "label": label,
                "children": lean_children,
                "activities": activity_rows,
                "keywords": _items(keywords),
                "risk_keywords": _items(risk_keywords),
            }
        )

    full_activities = [{"key": _slug(v), "value": v, "label": v} for v in FULL_ACTIVITIES]
    full_models = [{"key": _slug(v), "value": v, "label": v} for v in FULL_BUSINESS_MODELS]
    full_audience = [{"key": _slug(v), "value": v, "label": v} for v in FULL_AUDIENCE_SEGMENTS]

    return {
        "categories": sorted(categories, key=lambda item: item["label"].casefold()),
        "audience_groups": AUDIENCE_GROUPS,
        "languages": ANALYSIS_LANGUAGES,
        "catalog": {
            "activities": full_activities,
            "business_models": full_models,
            "audience_segments": full_audience,
            "languages": ANALYSIS_LANGUAGES,
        },
        "goals": base.get("goals", []),
        "source_playbooks": base.get("source_playbooks", {}),
        "meta": {
            "primary_categories": len(categories),
            "internal_directions": total_internal_directions,
            "activities": len(full_activities),
            "business_models": len(full_models),
            "audience_segments": len(full_audience),
            "analysis_languages": len(ANALYSIS_LANGUAGES),
            "searchable": True,
            "version": 3,
        },
    }
